# Verification of g(x) = x for small cases in S
def check_good_function(g):
    # Test Condition (3)
    if g(1) != 1:
        return False

    # Test Condition (1) for a small set of pairs
    S_small = [2, 3, 4, 5, 6, 7, 8, 9, 10, 12]
    for a in S_small:
        for b in S_small:
            if a >= b: continue
            ab = a * b
            if ab not in S_small: continue # Only checking pairs whose product is in the small set for simplicity

            if g(ab) == 0:
                if g(a) != 0 and g(b) != 0:
                    # print(f"Condition (1) failed for {a}, {b}: g({ab}) = 0 but g({a})!=0 and g({b})!=0")
                    return False

    # Test Condition (2) for a small set of pairs where g(ab) != 0
    for a in S_small:
        for b in S_small:
            if a == b: continue
            ab = a * b
            if ab not in S_small: continue

            if g(ab) != 0:
                # Check if denominators are non-zero (guaranteed by loop structure)
                LHS = (g(a) - g(b)) / (a - b)
                RHS = (g(a) * g(b)) / g(ab)

                if abs(LHS - RHS) > 1e-9:
                    # print(f"Condition (2) failed for {a}, {b}: LHS={LHS}, RHS={RHS}")
                    return False
    return True

# Define g(x) = x
def g_identity(x):
    return x

# Define a test case for a potential zero function, e.g., g(2)=0, g(x)=x otherwise
# Note: This is highly complex to define globally while satisfying all constraints,
# but we test the local consistency derived from W3's notes.
# Since W3's analysis implies that for consistency, if g(3)=3, g(2) must be 2 if g(6) != 0.
# Let's stick to the strong case g(x)=x as the primary confirmed solution.

print("--- Verifying g(x) = x ---")
if check_good_function(g_identity):
    print("g(x) = x satisfies conditions (1), (2), and (3) on the tested small set of S.")
else:
    print("g(x) = x failed verification.")

